def parse_line(line):
    """Parse a line of the form 'LEVEL ts msg' into a dict.

    Returns {'level': str, 'ts': int, 'msg': str} on success,
    or None if the line is malformed (missing fields, non-integer ts,
    empty/whitespace-only input, or non-string input).
    """
    if not isinstance(line, str):
        return None
    stripped = line.strip()
    if not stripped:
        return None
    parts = stripped.split(maxsplit=2)
    if len(parts) < 3:
        return None
    level, ts_str, msg = parts
    try:
        ts = int(ts_str)
    except ValueError:
        return None
    return {"level": level, "ts": ts, "msg": msg}
